import { HookBus } from "../src/bus.ts";
import assert from "node:assert/strict";
import { registerAuditPlugin } from "../src/plugin.ts";

const bus = new HookBus();
const order = [];
const off = bus.on("tool.after", async () => { await new Promise(r => setTimeout(r, 10)); order.push(1); });
bus.on("tool.after", async () => { order.push(2); });
bus.on("tool.after", () => { order.push(3); });
await bus.emit("tool.after", {});
assert.deepEqual(order, [1, 2, 3]);

// error propagation, later handlers skipped
const bus2 = new HookBus();
const err = new Error("boom");
bus2.on("e", () => { throw err; });
let after = false;
bus2.on("e", () => { after = true; });
await assert.rejects(bus2.emit("e", {}), e => e === err);
assert.equal(after, false);

// unsubscribe during emit does not stop others
const bus3 = new HookBus();
const seen = [];
const off3 = bus3.on("t", () => { off3(); seen.push("a"); });
bus3.on("t", () => seen.push("b"));
await bus3.emit("t", {});
assert.deepEqual(seen, ["a", "b"]);
assert.equal(bus3.count("t"), 1);

// plugin: notice once, redaction before log, audit correct
const audit = [];
const pluginBus = new HookBus();
registerAuditPlugin(pluginBus, audit);
const res = { tool: "read", output: "password=hunter2 ok" };
await pluginBus.emit("tool.after", res);
const res2 = { tool: "write", output: "password=abc" };
await pluginBus.emit("tool.after", res2);
assert.deepEqual(audit, [
  "notice: tool output is audited",
  "read: password=[redacted] ok",
  "write: password=[redacted]",
]);
console.log("all contract checks pass");

